pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }

    // fuzz parameters include the two deciding values that are assigned in initialize
    function testFuzz_property(address _baseToken, address _nft, uint128 _virtualBaseTokenReserves, uint128 _virtualNftReserves, uint56 _changeFee, uint16 _feeRate, bytes32 _merkleRoot, bool _useStolenNftOracle, bool _payRoyalties) public {
        // Keep addresses wide but avoid zero-address for nft when interacting (safe to allow zero for baseToken as code handles it)
        vm.assume(_nft != address(0));

        // call initialize from this contract (factory/owner semantics do not affect initialize visibility)
        bool ok;
        try c.initialize(_baseToken, _nft, _virtualBaseTokenReserves, _virtualNftReserves, _changeFee, _feeRate, _merkleRoot, _useStolenNftOracle, _payRoyalties) {
            ok = true;
        } catch {
            // initialize may revert for some inputs (e.g., feeRate > 5000), in that case we don't inspect state
            ok = false;
        }

        // Only assert the invariant for cases where initialize returned normally.
        if (ok) {
            // Single assertion: feeRate() must equal the supplied _feeRate argument after successful initialize.
            assertTrue(c.feeRate() == _feeRate);
        }
    }
}

