pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }

    // fuzz parameter: feeRate candidate and changeFee candidate and an arbitrary caller
    function testFuzz_property(uint16 _feeRate, uint56 _changeFee, address caller) public {
        // Keep domain wide but avoid zero-address caller (EOA allowed though)
        vm.assume(caller != address(0));
        // feeRate has a contract check of <= 5000, keep both inside wide domain so reference accepts many inputs
        _feeRate = uint16(bound(_feeRate, 0, 10000)); // allow >5000 too to sometimes trigger revert
        // changeFee can be any uint56; keep wide
        _changeFee = uint56(bound(_changeFee, 0, type(uint56).max));

        // Try to call initialize as 'caller' and record whether it succeeded and the observed feeRate
        bool ok;
        vm.prank(caller);
        try c.initialize(address(0), address(0), uint128(1), uint128(1), _changeFee, _feeRate, bytes32(0), false, false) {
            ok = true;
        } catch {
            ok = false;
        }

        // Single assertion: if initialize succeeded, then the public getter feeRate() must equal the supplied _feeRate.
        // This is the universal property reference satisfies; the mutant (swapping assignments) will sometimes violate it.
        if (ok) {
            assertTrue(c.feeRate() == _feeRate);
        } else {
            // If initialization reverted (e.g., feeRate > 5000), then the property about post-state doesn't apply; still assert that initialize actually reverted
            // We assert that feeRate remains 0 when initialization failed (constructor default) — observe via getter.
            assertTrue(c.feeRate() == 0);
        }
    }
}

